static class Program {
 [STAThread] static void Main(string[] args) {
  CultureInfo.DefaultThreadCurrentCulture = new CultureInfo("pt-BR");
  Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);if(args.Any(a=>a.StartsWith("--preview")))Application.ThreadException+=(s,e)=>{File.WriteAllText(Path.Combine(Environment.CurrentDirectory,"work","ui-error.txt"),e.Exception.ToString());Application.Exit();};
  try {
   if(args.Contains("--materials")){var arg=args.First(a=>a.StartsWith("--data-root="));var store=new Store(arg.Substring(12));store.Save();return;}
   if(args.Contains("--stone")){var arg=args.First(a=>a.StartsWith("--data-root="));var store=new Store(arg.Substring(12));store.SetupStoneRates();return;}
   if(args.Contains("--upgrade28")){var arg=args.First(a=>a.StartsWith("--data-root="));var store=new Store(arg.Substring(12));store.SetupFourRates();store.Company["Origem Porto Meira confirmada"]="Sim";store.Save();return;}
   if(args.Contains("--test")){Tests.Run();AdvancedTests.Run();StrategyTests.Run();IntegrationTests.Run();MarketTests.Run();MarketEditTests.Run();MarkupTests.Run();DeliveryTests.Run();StoneTests.Run();MaterialsTests.Run();BatchConfirmTests.Run();return;}
   if(Path.GetFileName(Application.ExecutablePath).StartsWith("Instalar")){Install();return;}
   if(args.Contains("--import-market")){string importRoot=args.FirstOrDefault(a=>a.StartsWith("--data-root="));var imp=new Store(importRoot==null?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"VideiraGestao","Dados"):importRoot.Substring(12));int count=imp.ImportPortfolio();int filled=imp.FillMissingMarketReferences();File.WriteAllText(Path.Combine(Path.GetDirectoryName(Application.ExecutablePath),"market-import-result.txt"),"Referências preenchidas: "+filled+"; Produtos adicionados: "+count+"; rótulos Mercado: "+imp.Data.Tables["Mercado"].Rows.Count);return;}
   bool smoke=args.Any(a=>a.StartsWith("--preview"));
   string root=smoke?Path.Combine(Environment.CurrentDirectory,"work","VideiraPreview"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"VideiraGestao","Dados");
   using(var mutex=new System.Threading.Mutex(false,"Local\\VideiraGestao")) {
    if(!mutex.WaitOne(0)){MessageBox.Show("O VIDEIRA GESTÃO já está aberto.");return;}
    try {if(smoke){Application.Run(new MainForm(new Store(root),true,args.FirstOrDefault(a=>a.StartsWith("--preview"))??""));}else{using(var cloud=CloudStore.AskLogin()){if(cloud==null)return;var online=new Store(root);online.ConnectCloud(cloud);Application.Run(new MainForm(online,false,""));}}} finally{mutex.ReleaseMutex();}
   }
  }catch(Exception ex){if(args.Contains("--test")||args.Contains("--upgrade28")||args.Contains("--stone")||args.Contains("--materials")||args.Any(a=>a.StartsWith("--preview"))){System.IO.File.WriteAllText(Path.Combine(Path.GetDirectoryName(Application.ExecutablePath),"diagnostico.txt"),ex.ToString());return;}MessageBox.Show(ex.Message,"VIDEIRA GESTÃO",MessageBoxButtons.OK,MessageBoxIcon.Error);}
 }
 static void Install(){
  if(MessageBox.Show("Instalar VIDEIRA GESTÃO neste computador e criar um atalho na área de trabalho?","VIDEIRA GESTÃO • Instalador",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
  string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"VideiraGestao");Directory.CreateDirectory(dir);
  string exe=Path.Combine(dir,"VIDEIRA GESTÃO.exe"); File.Copy(Application.ExecutablePath,exe,true);
  Type t=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(t);
  object link=t.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"VIDEIRA GESTÃO.lnk")});
  link.GetType().InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{exe});
  link.GetType().InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{dir});
  link.GetType().InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);
  MessageBox.Show("Instalação concluída. Abra pelo atalho VIDEIRA GESTÃO na área de trabalho.\n\nEntre com sua conta para acessar os mesmos dados online neste computador.","VIDEIRA GESTÃO");
 }
}
partial class Store {
 public DataSet Data; public string Root; public string FileName {get{return Path.Combine(Root,"videira.xml");}}
 static DataTable Table(DataSet ds,string name,params string[] fields){var t=ds.Tables.Add(name);t.Columns.Add("Id",typeof(int));foreach(string f in fields){string[] p=f.Split(':');Type type=p.Length<2?typeof(string):p[1]=="n"?typeof(decimal):p[1]=="i"?typeof(int):typeof(DateTime);t.Columns.Add(p[0],type);}t.PrimaryKey=new[]{t.Columns["Id"]};return t;}
 public Store(string root){Root=root;Directory.CreateDirectory(root);Data=new DataSet("Videira");
  Table(Data,"Produtos","Código","Nome","Fornecedor","Custo:n","Preço:n","Estoque:n","Ativo");
  Table(Data,"Fornecedores","Nome","Telefone","Email","Observações");
  Table(Data,"Clientes","Nome","Telefone","Email","Observações");
  Table(Data,"Vendas","Data:d","Cliente","Pagamento","Taxa %:n","Total:n","Custo:n","Embalagem:n","Taxa R$:n","Resultado:n","Situação");
  Table(Data,"Itens","Venda:i","Produto:i","Código","Nome","Quantidade:n","Preço:n","Custo:n","Total:n");
  Table(Data,"Movimentos","Data:d","Produto:i","Código","Nome","Quantidade:n","Tipo","Observações");
  Table(Data,"Despesas","Data:d","Categoria","Descrição","Valor:n");
  Table(Data,"Taxas","Modalidade","Percentual:n");
  Upgrade(Data);if(System.IO.File.Exists(FileName)){Data.ReadXml(FileName,XmlReadMode.IgnoreSchema);Upgrade(Data);}
  else {Data.Tables["Taxas"].Rows.Add(1,"Débito",0m);Data.Tables["Taxas"].Rows.Add(2,"Crédito à vista",0m);Data.Tables["Taxas"].Rows.Add(3,"Crédito parcelado",0m);Save();}if(ImportInfiniteRates())Save();if(SetupDelivery())Save();if(SeedMaterials())Save();
 }
 public int Next(string table){return Data.Tables[table].Rows.Count==0?1:Data.Tables[table].AsEnumerable().Max(r=>(int)r["Id"])+1;}
 public void Save(){if(Cloud!=null){Cloud.Commit(Data);try{SaveLocal();}catch{}return;}SaveLocal();}
 public void SaveLocal(){string temp=FileName+".tmp";Data.WriteXml(temp,XmlWriteMode.WriteSchema);if(System.IO.File.Exists(FileName))System.IO.File.Replace(temp,FileName,FileName+".bak");else System.IO.File.Move(temp,FileName);}
 public void Atomic(Action a){DataSet old=Data.Copy();try{a();Save();}catch{Data=old;throw;}}
 public static decimal Money(decimal n){return Math.Round(n,2,MidpointRounding.AwayFromZero);}
 public int Sell(DataTable cart,string client,string payment,decimal rate,bool persist=true){int id=Next("Vendas");Action transaction=()=>{
  if(cart.Rows.Count==0)throw new Exception("Adicione ao menos um produto.");
  foreach(var g in cart.AsEnumerable().GroupBy(r=>(int)r["Produto"])) {var p=Data.Tables["Produtos"].Rows.Find(g.Key);if(p==null||p["Ativo"].ToString()!="Sim")throw new Exception("Produto indisponível.");if(g.Sum(r=>(decimal)r["Quantidade"])>(decimal)p["Estoque"])throw new Exception("Estoque insuficiente: "+p["Nome"]);}
  decimal total=0,cost=0,pack=0,extra=0;
  foreach(DataRow item in cart.Rows){var p=Data.Tables["Produtos"].Rows.Find(item["Produto"]);decimal q=(decimal)item["Quantidade"],price=(decimal)item["Preço"];if(q<=0||q!=Math.Truncate(q)||price<0)throw new Exception("Quantidade deve ser inteira e positiva; preço não pode ser negativo.");decimal line=Money(q*price);total+=line;cost+=Money(q*(decimal)p["Custo"]);pack+=Money(q*(decimal)p["Embalagem unitária"]);decimal other=Money(q*(decimal)p["Outros custos unitários"]+line*(decimal)p["Despesa variável %"]/100);extra+=other;
   Data.Tables["Itens"].Rows.Add(Next("Itens"),id,p["Id"],p["Código"],p["Nome"],q,price,p["Custo"],line,p["Embalagem unitária"],other,cart.Columns.Contains("Preço original")?item["Preço original"]:(object)price,cart.Columns.Contains("Desconto %")?item["Desconto %"]:(object)0m);
   p["Estoque"]=(decimal)p["Estoque"]-q;Move(p,-q,"Venda","Venda nº "+id);
  }
  decimal fee=Money(total*rate/100);Data.Tables["Vendas"].Rows.Add(id,DateTime.Now,client,payment,rate,total,cost,pack,fee,total-cost-pack-fee-extra,"Concluída",extra);
 };if(persist)Atomic(transaction);else transaction();return id;}
 public void Move(DataRow p,decimal q,string type,string note){Data.Tables["Movimentos"].Rows.Add(Next("Movimentos"),DateTime.Now,p["Id"],p["Código"],p["Nome"],q,type,note);}
 public void Cancel(int id){Atomic(()=>{var v=Data.Tables["Vendas"].Rows.Find(id);if(v==null||v["Situação"].ToString()!="Concluída")throw new Exception("Esta venda já está cancelada.");foreach(DataRow i in Data.Tables["Itens"].Select("Venda = "+id)){var p=Data.Tables["Produtos"].Rows.Find(i["Produto"]);p["Estoque"]=(decimal)p["Estoque"]+(decimal)i["Quantidade"];Move(p,(decimal)i["Quantidade"],"Cancelamento","Venda nº "+id);}v["Situação"]="Cancelada";});}
}
