 public NumericUpDown Number(string label,decimal value=0,decimal max=100000000, int decimals=2){var c=new NumericUpDown{Maximum=max,DecimalPlaces=decimals,Value=Math.Min(max,Math.Max(0,value)),ThousandsSeparator=true};Add(label,c);return c;}
 public ComboBox Choice(string label,string[] choices){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(choices);if(c.Items.Count>0)c.SelectedIndex=0;Add(label,c);return c;}
 public void Commit(Action action){var cancel=new Button{Text="Sair",Width=95,Height=32};Theme.Button(cancel);cancel.Click+=(s,e)=>Close();Buttons.Controls.Add(cancel);CancelButton=cancel;var save=new Button{Text="✓ Salvar",Width=120,Height=32};Theme.Button(save);save.Width=120;save.Click+=(s,e)=>{try{action();DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Verifique os dados",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};Buttons.Controls.Add(save);AcceptButton=save;}
}
