 void RefreshGrid(){string previousSort=grid.SortedColumn==null?null:grid.SortedColumn.Name;var previousDirection=grid.SortOrder==SortOrder.Descending?System.ComponentModel.ListSortDirection.Descending:System.ComponentModel.ListSortDirection.Ascending;DataTable t;string q=search==null?"":search.Text.Trim();
  if(page=="Produtos"||page=="Inventário"){t=db.Data.Tables["Produtos"].Copy();foreach(DataRow pending in t.Rows.Cast<DataRow>().ToArray())if(!(bool)pending["Confirmado"])t.Rows.Remove(pending);t.Columns.Add("Markup %",typeof(decimal));t.Columns.Add("Lucro unitário",typeof(decimal));foreach(string key in new[]{"Custo total R$","Gastos rateados R$","Taxa R$"})t.Columns.Add(key,typeof(decimal));t.Columns.Add("Cálculo de custos");foreach(DataRow r in t.Rows){decimal c=(decimal)r["Custo"],p=(decimal)r["Preço"];r["Markup %"]=c==0?0:Store.Money((p-c)/c*100);try{var x=db.CostsAt(r,p);r["Lucro unitário"]=Store.Money(x.Profit);r["Custo total R$"]=Store.Money(x.Base+x.Overhead+x.Fee+x.Variable);r["Gastos rateados R$"]=Store.Money(x.Overhead);r["Taxa R$"]=Store.Money(x.Fee);}catch(Exception ex){r["Cálculo de custos"]=ex.Message;}}}
  else if(page=="Entradas de estoque"||page=="Movimentações")t=db.Data.Tables["Movimentos"].Copy();
  else if(page=="Taxa de maquininha")t=db.Data.Tables["Taxas"].Copy();
  else if(page=="Gastos fixos"||page=="Gastos variáveis"){t=db.Data.Tables["Despesas"].Clone();foreach(DataRow r in db.Data.Tables["Despesas"].Rows)if(r["Categoria"].ToString()==page)t.ImportRow(r);}
  else if(page=="Embalagens"){t=new DataTable();t.Columns.Add("Venda",typeof(int));t.Columns.Add("Data",typeof(DateTime));t.Columns.Add("Unidades",typeof(decimal));t.Columns.Add("Custo embalagem",typeof(decimal));foreach(DataRow v in db.Data.Tables["Vendas"].Rows)if(v["Situação"].ToString()=="Concluída")t.Rows.Add(v["Id"],v["Data"],db.Data.Tables["Itens"].AsEnumerable().Where(r=>(int)r["Venda"]==(int)v["Id"]).Sum(r=>(decimal)r["Quantidade"]),v["Embalagem"]);}
  else if(page=="Resumo financeiro"){t=new DataTable();t.Columns.Add("Indicador");t.Columns.Add("Valor",typeof(decimal));var vs=db.Data.Tables["Vendas"].AsEnumerable().Where(r=>r["Situação"].ToString()=="Concluída");decimal sales=vs.Sum(r=>(decimal)r["Total"]),cost=vs.Sum(r=>(decimal)r["Custo"]),pack=vs.Sum(r=>(decimal)r["Embalagem"]),fee=vs.Sum(r=>(decimal)r["Taxa R$"]),fixedCost=db.Data.Tables["Despesas"].AsEnumerable().Where(r=>r["Categoria"].ToString()=="Gastos fixos").Sum(r=>(decimal)r["Valor"]),variable=db.Data.Tables["Despesas"].AsEnumerable().Where(r=>r["Categoria"].ToString()=="Gastos variáveis").Sum(r=>(decimal)r["Valor"]);t.Rows.Add("Vendas concluídas",sales);t.Rows.Add("Custo dos produtos vendidos",cost);t.Rows.Add("Embalagens • R$ 1 por unidade",pack);t.Rows.Add("Taxas da maquininha",fee);t.Rows.Add("Resultado das vendas",sales-cost-pack-fee);t.Rows.Add("Gastos fixos",fixedCost);t.Rows.Add("Gastos variáveis",variable);t.Rows.Add("Resultado após despesas",sales-cost-pack-fee-fixedCost-variable);}
  else t=db.Data.Tables[page].Copy();
  if(q.Length>0){foreach(DataRow r in t.Rows.Cast<DataRow>().ToArray())if(!(searchBy.SelectedIndex==1&&t.Columns.Contains("Código")?new[]{r["Código"]}:searchBy.SelectedIndex==2&&(t.Columns.Contains("Nome")||t.Columns.Contains("Descrição"))?new[]{r[t.Columns.Contains("Nome")?"Nome":"Descrição"]}:r.ItemArray).Any(x=>Convert.ToString(x).IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0))t.Rows.Remove(r);}
  if(stateFilter!=null&&stateFilter.SelectedIndex>0){string col=t.Columns.Contains("Ativo")?"Ativo":t.Columns.Contains("Situação")?"Situação":"";if(col!=""){string val=col=="Ativo"?(stateFilter.SelectedIndex==1?"Sim":"Não"):stateFilter.Text;foreach(DataRow r in t.Rows.Cast<DataRow>().ToArray())if(r[col].ToString()!=val)t.Rows.Remove(r);}}
  if(page=="Produtos"||page=="Inventário")t=t.DefaultView.ToTable(false,new[]{"Id","Código","Nome","Fornecedor","Estoque","Custo","Preço","Embalagem unitária","Ativo","Markup %","Lucro unitário","Custo total R$","Gastos rateados R$","Taxa R$","Cálculo de custos"});if(page=="Produtos"||page=="Inventário"){t.Columns.Add("Ordem numérica",typeof(decimal));foreach(DataRow row in t.Rows){decimal code;row["Ordem numérica"]=decimal.TryParse(row["Código"].ToString(),System.Globalization.NumberStyles.None,System.Globalization.CultureInfo.InvariantCulture,out code)?code:decimal.MaxValue;}}grid.DataSource=null;grid.AutoGenerateColumns=false;grid.Columns.Clear();foreach(DataColumn field in t.Columns)grid.Columns.Add(new DataGridViewTextBoxColumn{Name=field.ColumnName,DataPropertyName=field.ColumnName,HeaderText=field.ColumnName,ValueType=field.DataType,SortMode=DataGridViewColumnSortMode.Automatic});grid.DataSource=t;if(grid.Columns.Contains("Id"))grid.Columns["Id"].Visible=false;if(grid.Columns.Contains("Produto"))grid.Columns["Produto"].Visible=false;
  foreach(DataGridViewColumn col in grid.Columns){if(col.ValueType==typeof(decimal))col.DefaultCellStyle.Format="N2";if(col.ValueType==typeof(DateTime))col.DefaultCellStyle.Format="dd/MM/yyyy HH:mm";}
  if(page=="Produtos"||page=="Inventário"){foreach(DataGridViewRow row in grid.Rows){var bound=row.DataBoundItem as DataRowView;if(bound==null||bound.Row.IsNull("Id"))continue;var p=db.Data.Tables["Produtos"].Rows.Find(bound.Row["Id"]);if(p!=null&&(decimal)p["Estoque mínimo"]>0&&(decimal)p["Estoque"]<=(decimal)p["Estoque mínimo"])row.DefaultCellStyle.ForeColor=Color.Firebrick;}string[] shown={"Código","Nome","EAN","Fornecedor","Custo","Preço","Estoque","Embalagem unitária","Precificação automática","Ativo","Markup %","Lucro unitário","Custo total R$","Gastos rateados R$","Taxa R$","Cálculo de custos"};foreach(DataGridViewColumn col in grid.Columns)col.Visible=shown.Contains(col.Name);grid.Columns["Embalagem unitária"].HeaderText="Embalagem R$";}
  foreach(DataGridViewColumn c in grid.Columns){c.MinimumWidth=c.Name=="Nome"||c.Name=="Descrição"?230:c.Name=="Fornecedor"?145:c.Name=="Cálculo de custos"?150:c.HeaderText.Length>14?125:c.HeaderText.Length>10?110:75;c.FillWeight=c.Name=="Nome"||c.Name=="Descrição"||c.Name=="Indicador"?280:c.Name=="Fornecedor"||c.Name=="Cliente"||c.Name=="Observações"?160:85;if(c.ValueType==typeof(decimal))c.DefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleRight;}
  if(page=="Produtos"||page=="Inventário"){grid.Columns["Código"].SortMode=DataGridViewColumnSortMode.Programmatic;string sort=previousSort!=null&&grid.Columns.Contains(previousSort)?previousSort:"Ordem numérica";grid.Sort(grid.Columns[sort],previousDirection);if(sort=="Ordem numérica")grid.Columns["Código"].HeaderCell.SortGlyphDirection=previousDirection==System.ComponentModel.ListSortDirection.Ascending?SortOrder.Ascending:SortOrder.Descending;}summary.Text="Registros encontrados: "+t.Rows.Count+(page=="Resumo financeiro"?" • Acumulado de todo o histórico. Gastos fixos são lançados por período.":page=="Produtos"?" • Resultado após fornecedor, embalagem, gastos rateados, taxa de referência e outros custos. Markup % permanece sobre fornecedor.":page=="Taxa de maquininha"?" • Stone: cartão somente 1x. Pix por transferência sem taxa; Pix na maquininha 0,99%. Mesmo preço de venda, sem desconto.":"");
 }
 void Contact(DataRow r){string table=page;using(var d=new Dialog("Cadastro • "+table)){var name=d.TextField("Nome",r==null?"":r["Nome"].ToString());var phone=d.TextField("Telefone",r==null?"":r["Telefone"].ToString());var email=d.TextField("E-mail",r==null?"":r["Email"].ToString());var note=d.TextField("Observações",r==null?"":r["Observações"].ToString());d.Commit(()=>{if(string.IsNullOrWhiteSpace(name.Text))throw new Exception("Informe o nome.");db.Atomic(()=>{if(r==null)db.Data.Tables[table].Rows.Add(db.Next(table),name.Text.Trim(),phone.Text,email.Text,note.Text);else{r["Nome"]=name.Text.Trim();r["Telefone"]=phone.Text;r["Email"]=email.Text;r["Observações"]=note.Text;}});});if(d.ShowDialog(this)==DialogResult.OK)RefreshGrid();}}
 ComboBox Products(){var c=new ComboBox{BindingContext=new BindingContext(),DropDownStyle=ComboBoxStyle.DropDownList};c.DataSource=db.Data.Tables["Produtos"].AsEnumerable().Where(r=>r["Ativo"].ToString()=="Sim"&&(bool)r["Confirmado"]).Select(r=>new ProductChoice{Id=(int)r["Id"],Text=r["Código"]+" • "+r["Nome"]}).ToList();c.DisplayMember="Text";return c;}
 void Entry(){using(var d=new Dialog("Entrada de estoque")){var p=Products();d.Add("Produto",p);var quantity=d.Number("Quantidade",1,100000000,0);var note=d.TextField("Observações");d.Commit(()=>{if(p.SelectedItem==null||quantity.Value<=0)throw new Exception("Selecione produto e quantidade maior que zero.");db.Atomic(()=>{var r=db.Data.Tables["Produtos"].Rows.Find(((ProductChoice)p.SelectedItem).Id);r["Estoque"]=(decimal)r["Estoque"]+quantity.Value;db.Move(r,quantity.Value,"Entrada",note.Text);});});if(d.ShowDialog(this)==DialogResult.OK)RefreshGrid();}}
 void Rate(DataRow r){using(var d=new Dialog("Taxa de maquininha")){var mode=d.TextField("Modalidade",r==null?"":r["Modalidade"].ToString());var rate=d.Number("Taxa %",r==null?0:(decimal)r["Percentual"],100,4);d.Commit(()=>{if(string.IsNullOrWhiteSpace(mode.Text))throw new Exception("Informe a modalidade.");if(mode.Text.Trim().Equals("Pix",StringComparison.OrdinalIgnoreCase)||mode.Text.Trim().Equals("Dinheiro",StringComparison.OrdinalIgnoreCase))throw new Exception("Pix e dinheiro já são formas de pagamento sem taxa neste cadastro. Use uma modalidade de cartão.");if(db.Data.Tables["Taxas"].AsEnumerable().Any(x=>x!=r&&string.Equals(x["Modalidade"].ToString(),mode.Text.Trim(),StringComparison.OrdinalIgnoreCase)))throw new Exception("Modalidade já cadastrada.");db.Atomic(()=>{if(r==null)db.Data.Tables["Taxas"].Rows.Add(db.Next("Taxas"),mode.Text.Trim(),rate.Value);else{r["Modalidade"]=mode.Text.Trim();r["Percentual"]=rate.Value;}});});if(d.ShowDialog(this)==DialogResult.OK)RefreshGrid();}}
 void Expense(DataRow r){string category=page;using(var d=new Dialog(category)){var date=new DateTimePicker{Format=DateTimePickerFormat.Short,Value=r==null?DateTime.Today:(DateTime)r["Data"]};d.Add("Data",date);var desc=d.TextField("Descrição",r==null?"":r["Descrição"].ToString());var val=d.Number("Valor R$",r==null?0:(decimal)r["Valor"]);d.Commit(()=>{if(string.IsNullOrWhiteSpace(desc.Text)||val.Value<=0)throw new Exception("Informe descrição e valor maior que zero.");db.Atomic(()=>{if(r==null)db.Data.Tables["Despesas"].Rows.Add(db.Next("Despesas"),date.Value.Date,category,desc.Text.Trim(),val.Value);else{r["Data"]=date.Value.Date;r["Descrição"]=desc.Text.Trim();r["Valor"]=val.Value;}});});if(d.ShowDialog(this)==DialogResult.OK)RefreshGrid();}}
 void ViewSale(){int id=(int)Selected("Vendas")["Id"];using(var f=new Form{Text="Itens da venda nº "+id,Size=new Size(950,450),StartPosition=FormStartPosition.CenterParent}){var t=db.Data.Tables["Itens"].Clone();foreach(DataRow r in db.Data.Tables["Itens"].Select("Venda = "+id))t.ImportRow(r);var g=new DataGridView{Dock=DockStyle.Fill,DataSource=t,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};f.Controls.Add(g);f.ShowDialog(this);}}
 void Backup(){using(var d=new SaveFileDialog{Filter="Backup Videira (*.xml)|*.xml",FileName="Videira-backup-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".xml"})if(d.ShowDialog(this)==DialogResult.OK){db.Data.WriteXml(d.FileName,XmlWriteMode.WriteSchema);MessageBox.Show("Backup salvo.");}}
 void Restore(){using(var d=new OpenFileDialog{Filter="Backup Videira (*.xml)|*.xml"})if(d.ShowDialog(this)==DialogResult.OK){var incoming=new DataSet();incoming.ReadXml(d.FileName,XmlReadMode.ReadSchema);if(incoming.Tables.Contains("Produtos")&&incoming.Tables.Contains("Vendas")&&incoming.Tables.Contains("Itens"))Store.Upgrade(incoming);foreach(DataTable t in db.Data.Tables){if(!incoming.Tables.Contains(t.TableName))throw new Exception("Backup inválido: tabela ausente.");foreach(DataColumn c in t.Columns)if(!incoming.Tables[t.TableName].Columns.Contains(c.ColumnName)||incoming.Tables[t.TableName].Columns[c.ColumnName].DataType!=c.DataType)throw new Exception("Backup incompatível.");}if(MessageBox.Show("Substituir todos os dados pelo backup selecionado? Uma cópia dos dados atuais será preservada.","Restaurar backup",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;db.Data.WriteXml(Path.Combine(db.Root,"antes-restauracao-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".xml"),XmlWriteMode.WriteSchema);Store.Upgrade(incoming);db.Atomic(()=>db.Data=incoming);Home();MessageBox.Show("Backup restaurado.");}}
 void Export(){using(var d=new SaveFileDialog{Filter="Planilha CSV (*.csv)|*.csv",FileName=page+".csv"})if(d.ShowDialog(this)==DialogResult.OK){var t=(DataTable)grid.DataSource;Func<object,string> quote=x=>"\""+Convert.ToString(x).Replace("\"","\"\"")+"\"";using(var w=new StreamWriter(d.FileName,false,new System.Text.UTF8Encoding(true))){w.WriteLine(string.Join(";",t.Columns.Cast<DataColumn>().Select(c=>quote(c.ColumnName))));foreach(DataRow r in t.Rows)w.WriteLine(string.Join(";",r.ItemArray.Select(x=>quote((x is string&&"=+-@".Contains(((string)x).FirstOrDefault()))?"'"+x:x))));}MessageBox.Show("Relatório exportado.");}}
}
class ProductChoice {public int Id{get;set;}public string Text{get;set;}}
static class Tests {
 static void Assert(bool b,string message){if(!b)throw new Exception(message);}
 public static void Run(){string root=Path.Combine(Environment.CurrentDirectory,"work","VideiraTests-"+Guid.NewGuid());var s=new Store(root);s.Data.Tables["Produtos"].Rows.Add(1,"V001","Vinho","Fornecedor",50m,80m,10m,"Sim");s.Save();var cart=new DataTable();cart.Columns.Add("Produto",typeof(int));cart.Columns.Add("Quantidade",typeof(decimal));cart.Columns.Add("Preço",typeof(decimal));cart.Rows.Add(1,2m,80m);cart.Rows.Add(1,1m,80m);int id=s.Sell(cart,"Teste","Crédito",2.5m);var v=s.Data.Tables["Vendas"].Rows.Find(id);Assert((decimal)v["Embalagem"]==3m,"Embalagem");Assert((decimal)v["Total"]==240m,"Total");Assert((decimal)v["Taxa R$"]==6m,"Taxa");Assert((decimal)v["Resultado"]==81m,"Resultado");Assert((decimal)s.Data.Tables["Produtos"].Rows.Find(1)["Estoque"]==7m,"Baixa de estoque");s=new Store(root);Assert(s.Data.Tables["Vendas"].Rows.Count==1,"Persistência");cart.Rows.Clear();cart.Rows.Add(1,8m,80m);bool failed=false;try{s.Sell(cart,"Teste","Pix",0);}catch{failed=true;}Assert(failed&&s.Data.Tables["Vendas"].Rows.Count==1&&(decimal)s.Data.Tables["Produtos"].Rows.Find(1)["Estoque"]==7m,"Rollback");s.Cancel(id);Assert((decimal)s.Data.Tables["Produtos"].Rows.Find(1)["Estoque"]==10m,"Cancelamento");failed=false;try{s.Cancel(id);}catch{failed=true;}Assert(failed&&(decimal)s.Data.Tables["Produtos"].Rows.Find(1)["Estoque"]==10m,"Cancelamento duplicado");System.IO.File.WriteAllText(Path.Combine(Environment.CurrentDirectory,"work","test-result.txt"),"PASS: embalagem por unidade, total, taxa, resultado, estoque, persistência, venda sem estoque, rollback e cancelamento.");Directory.Delete(root,true);}
}
